  let version = 'unknown';
  try {
    version = require('./package.json').version;
  } catch (_) {
    // package.json not present — leave as 'unknown'.
  }

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version,
    uptime: process.uptime(),  // seconds since the Node process started
  });
});

