const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();

// Resolve the server version once at startup:
//   1. Prefer the value injected by `npm start` / `npm run …`
//   2. Fall back to reading package.json from the project root
//   3. If neither is available, use 'unknown'
function resolveVersion() {
  if (process.env.npm_package_version) {
    return process.env.npm_package_version;
  }
  try {
    const pkg = JSON.parse(
      fs.readFileSync(path.join(__dirname, 'package.json'), 'utf8')
    );
    return pkg.version || 'unknown';
  } catch {
    return 'unknown';
  }
}

const SERVER_VERSION = resolveVersion();

// Required environment variable names.
// Only the *names* are stored here — values are never read or exposed.
const REQUIRED_ENV_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    version: SERVER_VERSION,
    uptime: process.uptime(),   // seconds since the Node process started
    timestamp: new Date().toISOString(),
  });
});

// /ready returns 200 only when every required environment variable is present.
// Missing variable *names* are reported so operators can diagnose problems,
// but no values are ever included in the response.
